import csv
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(directory, name):
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        return []
    with open(path, encoding="utf-8-sig", newline="") as handle:
        text = handle.read()
    rows = []
    reader = csv.reader(io.StringIO(text))
    header = None
    for record in reader:
        if not record or all(not field.strip() for field in record):
            continue
        if header is None:
            header = [field.strip() for field in record]
            continue
        row = {}
        for index, column in enumerate(header):
            row[column] = record[index].strip() if index < len(record) else ""
        rows.append(row)
    return rows


def parse_time(value):
    hours, minutes, seconds = value.split(":")
    return int(hours) * 3600 + int(minutes) * 60 + int(seconds)


def parse_feed_date(value):
    return date(int(value[0:4]), int(value[4:6]), int(value[6:8]))


WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]


def stamp(instant, zone):
    local = instant.astimezone(zone)
    text = local.strftime("%Y-%m-%dT%H:%M:%S")
    offset = local.utcoffset()
    total = int(offset.total_seconds())
    sign = "+" if total >= 0 else "-"
    total = abs(total)
    return "%s%s%02d:%02d" % (text, sign, total // 3600, total % 3600 // 60)


def main(input_dir, output_file):
    with open(os.path.join(input_dir, "request.json"), encoding="utf-8-sig") as handle:
        request = json.load(handle)
    service_dates = sorted(set(request["service_dates"]))

    agencies = read_csv(input_dir, "agency.txt")
    agency_zone = {row["agency_id"]: row["agency_timezone"] for row in agencies}
    default_zone = agencies[0]["agency_timezone"]
    stops = {row["stop_id"]: row for row in read_csv(input_dir, "stops.txt")}
    routes = {row["route_id"]: row for row in read_csv(input_dir, "routes.txt")}
    trips = {row["trip_id"]: row for row in read_csv(input_dir, "trips.txt")}
    calendar = {row["service_id"]: row for row in read_csv(input_dir, "calendar.txt")}
    exceptions = {}
    for row in read_csv(input_dir, "calendar_dates.txt"):
        exceptions[(row["service_id"], row["date"])] = row["exception_type"]
    frequencies = {}
    for row in read_csv(input_dir, "frequencies.txt"):
        frequencies.setdefault(row["trip_id"], []).append(row)

    stop_times = {}
    for row in read_csv(input_dir, "stop_times.txt"):
        stop_times.setdefault(row["trip_id"], []).append(row)
    for rows in stop_times.values():
        rows.sort(key=lambda row: int(row["stop_sequence"]))

    def board_stop_of(stop_id):
        stop = stops[stop_id]
        parent = stop.get("parent_station", "")
        if parent and parent in stops:
            return parent
        return stop_id

    def zone_of(stop_id):
        name = stops[stop_id].get("stop_timezone", "") or default_zone
        return name

    def runs(service_id, day):
        key = (service_id, day.strftime("%Y%m%d"))
        kind = exceptions.get(key)
        if kind == "1":
            return True
        if kind == "2":
            return False
        row = calendar.get(service_id)
        if row is None:
            return False
        if not (parse_feed_date(row["start_date"]) <= day <= parse_feed_date(row["end_date"])):
            return False
        return row[WEEKDAYS[day.weekday()]] == "1"

    def stop_time_values(rows):
        times = []
        for row in rows:
            value = row.get("departure_time", "") or row.get("arrival_time", "")
            times.append(parse_time(value) if value else None)
        known = [index for index, value in enumerate(times) if value is not None]
        for before, after in zip(known, known[1:]):
            steps = after - before
            for index in range(before + 1, after):
                times[index] = times[before] + (
                    (times[after] - times[before]) * (index - before)) // steps
        return times

    boards = {}
    for stop_id, stop in stops.items():
        if stop.get("location_type", "") in ("", "0") and not stop.get("parent_station", ""):
            boards[stop_id] = stop
        elif stop.get("location_type", "") == "1":
            boards[stop_id] = stop

    result = []
    per_board = {}
    for day in service_dates:
        day_date = date.fromisoformat(day)
        for trip_id, trip in trips.items():
            if not runs(trip["service_id"], day_date):
                continue
            rows = stop_times.get(trip_id)
            if not rows:
                continue
            route = routes[trip["route_id"]]
            agency = route["agency_id"]
            zone = ZoneInfo(agency_zone[agency])
            noon = datetime(day_date.year, day_date.month, day_date.day, 12, tzinfo=zone)
            origin = noon.astimezone(timezone.utc) - timedelta(hours=12)
            label = route.get("route_short_name", "") or route.get("route_long_name", "")
            last_stop = board_stop_of(rows[-1]["stop_id"])
            last_name = stops[last_stop]["stop_name"]
            times = stop_time_values(rows)
            first_time = times[0]
            windows = frequencies.get(trip_id)
            for index, row in enumerate(rows):
                if index == len(rows) - 1 or row.get("pickup_type", "") == "1":
                    continue
                headsign = row.get("stop_headsign", "") or trip.get("trip_headsign", "") or last_name
                board_id = board_stop_of(row["stop_id"])
                board_zone = ZoneInfo(zone_of(board_id))
                platform = stops[row["stop_id"]].get("platform_code", "") or None
                entries = []
                if not windows:
                    entries.append(("scheduled", times[index], None, None))
                else:
                    offset = times[index] - first_time
                    for window in windows:
                        start = parse_time(window["start_time"])
                        end = parse_time(window["end_time"])
                        headway = int(window["headway_secs"])
                        if start >= end:
                            continue
                        count = (end - start - 1) // headway + 1
                        if window.get("exact_times", "") == "1":
                            for step in range(count):
                                entries.append(("scheduled", start + step * headway + offset, None, None))
                        else:
                            entries.append(("interval", start + offset,
                                            start + (count - 1) * headway + offset, headway))
                for kind, begin, until, headway in entries:
                    instant = origin + timedelta(seconds=begin)
                    until_text = None
                    if until is not None:
                        until_text = stamp(origin + timedelta(seconds=until), board_zone)
                    per_board.setdefault((board_id, day), []).append((
                        (instant, label, headsign, trip_id, platform is not None, platform or ""),
                        {
                            "kind": kind,
                            "time": stamp(instant, board_zone),
                            "until": until_text,
                            "headway_secs": headway,
                            "route": label,
                            "headsign": headsign,
                            "trip": trip_id,
                            "platform": platform,
                            "agency": agency,
                        }))

    for stop_id in sorted(boards):
        stop = boards[stop_id]
        for day in service_dates:
            entries = per_board.get((stop_id, day), [])
            entries.sort(key=lambda entry: entry[0])
            result.append({
                "stop_id": stop_id,
                "name": stop["stop_name"],
                "timezone": zone_of(stop_id),
                "service_date": day,
                "departures": [entry[1] for entry in entries],
            })

    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump({"service_dates": service_dates, "boards": result}, handle, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
